def page(path, title, body, prefix="../", user_prefix=""):
    target = BASE / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(
        HEAD.format(title=title, prefix=prefix, user_prefix=user_prefix)
        + body
        + FOOT.format(prefix=prefix),
        encoding="utf-8",
    )


